def run_cli() -> None:
    args = parse_args()
    pop = 50 if getattr(args, "smoke_test", False) else args.population_size
    days = 3 if getattr(args, "smoke_test", False) else args.time_horizon_days
    include_disease = False if getattr(args, "smoke_test", False) else args.include_disease_module
    config: Dict[str, Any] = {}
    if getattr(args, "config", None):
        try:
            with open(args.config, "r", encoding="utf-8") as f:
                config = json.load(f)
        except Exception as e:
            print(f"Warning: failed to read config {args.config}: {e}", file=sys.stderr)
    sim = SocialAdoptionSimulation(population_size=pop, time_horizon_days=days, random_seed=args.random_seed,
                                   include_disease_module=include_disease, config_params=config,
                                   network_mean_degree=args.network_mean_degree,
                                   network_rewiring_prob=args.network_rewiring_prob)
    sim.run()
    out_json = args.output
    csv_path = os.path.splitext(out_json)[0] + ".csv"
    sim.save_json(out_json, metadata={"args": vars(args)})
    sim.save_results(csv_path)
    if not getattr(args, "no_stdout", False):
        payload = {"metrics": sim.metrics}
        if getattr(args, "with_validation", False):
            payload["validation"] = sim.validation_report
        print(json.dumps(payload, indent=2, sort_keys=True))
    if getattr(args, "plot", False):
        sim.visualize()

def main() -> None:
    run_cli()

